// Pairwise addition: result[i] = a[2*i] + a[2*i + 1]
// Assumes `a.len()` is even.
fn pairwise_addition(a: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(a.len() / 2);

    for chunk in a.chunks_exact(2) {
        result.push(chunk[0] + chunk[1]);
    }

    result
}

fn main() {
    // Example usage
    let a = vec![1, 2, 3, 4, 10, -5, 7, 8];
    let r = pairwise_addition(a);
    println!("{r:?}"); // [3, 7, 5, 15]
}